def hydrate_time(nanoseconds, tz=None):
    from datetime import datetime, timezone

    if nanoseconds > 0:
        return datetime.fromtimestamp(nanoseconds / 1000000000.0, timezone.utc)
    elif nanoseconds < 0:
        return datetime.fromtimestamp(nanoseconds / 1000000000.0 - 86400.0, timezone.utc)
    else:
        return datetime.now(timezone.utc)

