class Point():
    def __init__(self, lat, lon, time=None):
        self.lat = lat
        self.lon = lon
        self.time = time

def from_json(json):
    """ Creates Point instance from JSON representation

    Args:
        json (:obj:`dict`): Must have at least the following keys: lat (float),
            lon (float), time (string in iso format). Example,
            {
                "lat": 9.3470298,
                "lon": 3.79274,
                "time": "2016-07-15T15:27:53.574110"
            }
        json: map representation of Point instance
    Returns:
        :obj:`Point`
    """
    return Point(
        lat=json['lat'],
        lon=json['lon'],
        time=isostr_to_datetime(json['time'])
    )

def is_valid_datetime(time):
    try:
        parse(time)
    except ValueError:
        return False
    return True

def isostr_to_datetime(iso):
    return datetime.fromisoformat(iso)

