    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: The Point object as a dictionary containing all attributes
    """
    result = {
        'lat': value.lat,
        'lon': value.lon
    }
    if value.time != None:
        result['time'] = value.time.isoformat()
    return result

