from neo4j import Connection, WatchdogTimer, UnitOfWork
import logging

logger = logging.getLogger('neo4j')

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx):
            metadata_values = dict(metadata or {})
            with UnitOfWork(tx=tx, metadata=metadata_values) as uow:
                uow.set_timeout(timeout)  # if timeout is not specified, use the default from the database
                return func(uow)
        return wrapper
    return decorator

