def round_half_to_even(n):
    """
    Rounds half way to the nearest even number.

    :param n:
    :return:
    """
    if n % 2 == 0:
        return n
    elif n % 1 == 0.5:
        return n - 1 if n > 0 else n + 1
    else:
        return round(n)

