import re

def parse_version(s: str) -> tuple[int, ...]:
    """
    Poor man's version comparison

    Args:
        s (str): Version string.

    Returns:
        tuple[int, ...]: A tuple of integers representing the version components.
    """
    m = re.match(r'(\d+)\.(\d+)\.(\d+)(?:-(\d+)(?:(?:\.(\d+))?)?)?(?:\.post(\d+)?)?(?:\.dev(\d+))?', s)
    if not m:
        raise ValueError(f"Invalid version string: {s}")
    components = [int(x) for x in m.groups(1)]
    if m.group(5):
        components.append(int(m.group(5)))
    elif m.group(6):
        components.append(0)
    if m.group(7):
        components.append(int(m.group(7)))
    return tuple(components)

