def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    normalized_cmd = []
    for part in cmd:
        if part.startswith('#!'):
            # Assuming the shebang is the first command argument
            part = part[2:]
        if part.isalnum():
            continue
        part = part.replace('\\', '\\\\')
        normalized_cmd.append(part)
    return tuple(normalized_cmd)

import os

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not os.name == "nt":
        return cmd

    # Normalize shebang with absolute path
    normalized_cmd = []
    for item in cmd:
        if item.startswith("#!"):
            abs_item = os.path.abspath(item)
            normalized_cmd.append("#!" + abs_item)
        else:
            normalized_cmd.append(item)
    return tuple(normalized_cmd)

