def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        memoized_results = {k: None for k in range(maxsize)}
        memory_timestamps = {k: 0 for k in range(maxsize)}
        memory_type_flags = {k: False for k in range(maxsize)}
        def _get_cache_key(*args, **kwargs):
            key = tuple(args) + tuple(kwargs.items())
            return hash(key)
        def _is_valid_cache_item(key):
            return (memory_timestamps[key] + ttl) >= timer()
        def _delete_old_cache_items():
            present_keys = set(memoized_results.keys())
            to_delete = present_keys - {(key for key in present_keys if _is_valid_cache_item(key))}
            for key in to_delete:
                memory_timestamps[key] = 0  # Ensure invalidation on the next insert
        def _initialize_cache():
            _delete_old_cache_items()
            for _ in range(maxsize):
                memoized_results[_] = None
                memory_timestamps[_] = 0
                memory_type_flags[_] = False
        _initialize_cache()  # Initialize the cache with default values

        def _tuple_contains_subsequence(tuple1, tuple2):
            return tuple1[0:len(tuple2)] == tuple2

        @functools.wraps(func)
        def inner(*args, **kwargs):
            key = _get_cache_key(*args, **kwargs)
            if key in memoized_results:
                timestamp = memory_timestamps[key]
                value = memoized_results[key]
                if _is_valid_cache_item(key) and _tuple_contains_subsequence(memory_type_flags[key], typed):
                    memoized_results[key] = result
                    memory_timestamps[key] = timer()
                    return value
            result = func(*args, **kwargs)
            if typed:
                memoized_results[key] = (result, (args, kwargs))
            else:
                memoized_results[key] = result
            memory_timestamps[key] = timer()
            return result
