def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    seen = set()
    min_sorted_bases = []

    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            min_sorted_bases.append(cls)

    return min_sorted_bases

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    from collections import OrderedDict
    min_bases = OrderedDict()
    for cls in classes:
        if cls not in min_bases:
            min_bases[cls] = cls
        else:
            # Replace cls with its parent class
            parent = next((parent for parent in reversed(cls.mro()) if parent not in min_bases), None)
            if parent is None:
                break
            min_bases[cls] = parent
    return list(min_bases.values())

