def fill(self, coord, weight=1):
        """
        Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.

        Parameters
        ----------
        coord : array-like
            Coordinates to be filled in the histogram.

        weight : float, optional
            Weight to be applied to the given *coord* at each position.
            The default is 1.

        """
        def _check_coord(coord, hist):
            x = coord[0]
            y = coord[1]
            if x < hist._bin_edges[0] or y < hist._bin_edges[1]:
                return False, "Coordinate {c} is outside the histogram edges.".format(c=coord)
            if x > hist._bin_edges[-1] or y > hist._bin_edges[-2]:
                return False, "Coordinate {c} is outside the histogram edges.".format(c=coord)
            return True, ""

        if not isinstance(coord, np.ndarray):
            coord = np.array(coord)

        hist = self._histograms[0]
        filled = []
        for c in coord:
            valid, message = _check_coord(c, hist)
            if not valid:
                filled.append(message)
            else:
                filled.append(hist.fill(c[0], c[1], weight=weight))
        return filled

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not min(coord) >= xmin and max(coord) <= xmax:
        return
    for i in range(len(coord)):
        self.hist[coord[i]] += weight

