def _validate_labels(labels):
    """Check that keys and values in the given labels match against their respective
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expressions. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    def validate_key(key, regex):
        if isinstance(key, str) and not regex.fullmatch(key):
            raise ValidationError({"key": f"Label key '{key}' does not match the regex {regex}"})

    def validate_value(value, regex):
        if not isinstance(value, (str, bytes)):
            raise ValidationError({"value": "expected string or bytes-like object"})
        elif not regex.fullmatch(value):
            raise ValidationError({"value": f"Label value '{value}' does not match the regex {regex}"})

    messages = []
    for label in labels:
        if not isinstance(label, str):
            raise ValidationError({"label": f"Expected string for label, but got {type(label).__name__}"})

        key_value_pairs = label.split("=", 1)
        if len(key_value_pairs) != 2:
            raise ValidationError({"label": "Label must be in the format 'key=value' or 'key=[value]'"})

        key, value = key_value_pairs

        validate_key(key, regex=r'^[\w]+(?:\.\w+)*$')

        if key.startswith("$"):
            if value != "invalid":
                raise ValidationError({"label": f"Label key '{key}' has a value that does not match the regex ^invalid$"})
        else:
            validate_value(value, regex=r'^[\w]+(?:\.\w+)*$')

    return messages

