            default observer schema
    """
    for resource in app.spec.manifest:
        # Check if a custom observer schema has already been specified
        if not resource.get('observer_schema'):
            # Generate default observer schema
            observer_schema = {
                'type': 'dict',
                'properties': {
                    'name': {
                        'type': 'string',
                        'description': 'Name of the observer',
                        'required': True
                    },
                    'description': {
                        'type': 'string',
                        'description': 'Description of the observer',
                        'required': False
                    }
                },
                'required': ['name']
            }
            # Apply metadata or additional properties based on resource metadata
            if resource.get('metadata'):
                observer_schema['metadata'] = resource['metadata']
            # Add additional properties specific to the resource
            if resource.get('apiVersion'):
                observer_schema['apiVersion'] = resource['apiVersion']
                observer_schema['kind'] = resource['kind']
            # Update the spec with the default observer schema
            app.spec.resources[resource['name']].observer_schema = observer_schema

