def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
            contains the set of in-style parameters. It maps each parameter
            (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
            is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
            If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
            *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	A :class:`list` containing each set of converted out-style
            parameters (:class:`dict` or :class:`list`).
    """
    from dataclasses import dataclass
    from collections import namedtuple
    from typing import List, Dict, Any, Union, AnyStr

    @dataclass
    class InOutParam:
        in_style_value: Any

    class InParams(Mapping):
        def __init__(self, in_params: Union[Dict[Union[str, int], Any]], in_style: str):
            self.in_params = in_params
            self.in_style = in_style

        def __getitem__(self, key: Union[str, int]):
            if self.in_style == "named":
                return InOutParam(self.in_params[key])
            elif self.in_style == "ordinal":
                return InOutParam(self.in_params[int(key)])
            else:
                raise ValueError(f"Unknown in-style: {self.in_style}")

        def __iter__(self):
            return self.in_params.items()

        def __len__(self):
            return len(self.in_params)

    class OutParams(Literal["in", "out", "both", "none"]):
        pass

    class OutParam(Mapping):
        def __init__(self, out_params: Union[Dict[Union[str, int], Any]], out_style: str):
            self.out_params = out_params
            self.out_style = out_style

        def __getitem__(self, key: Union[str, int]):
            return InOutParam(self.out_params[key])

        def __iter__(self):
            return self.out_params.items()

        def __len__(self):
            return len(self.out_params)

    def compile_insert(self, query: AnyStr, values: Union[Dict[Union[str, int], Any], Iterable[Sequence[Any]]], out_style: OutParam = OutParam.out) -> Tuple[AnyStr, List[AnyStr]]:
        """
        Compile an insert SQL statement

        :param query: A QueryBuilder instance
        :type query: QueryBuilder

        :param values: The values to insert
        :type values: dict or list

        :param out_style: Style for out-parameters. Can be "in", "out",
            "both", or "none".
        :type out_style: OutParam

        :return: The compiled statement
        :rtype: str
        """
        table = self.wrap_table(query.from__)

        if not isinstance(values, list):
            values = [values]

        columns = self.columnize(values[0].keys())

        # We need to build a list of parameter place-holders of values that are bound
        # to the query. Each insert should have the exact same amount of parameter
        # bindings so we can just go off the first list of values in this array.
        parameters = self.parameterize(values[0].values())

        value = ['(%s)' % parameters] * len(values)

        parameters = ', '.join(value)

        compile_mode = {
            OutParam.out: f'INSERT INTO {table} ({columns}) VALUES ({parameters})',
            OutParam.in: f'INSERT INTO {table} ({columns}) VALUES %s',
            OutParam.both: f'INSERT INTO {table} ({columns}) VALUES ({parameters})',
            OutParam.none: f'INSERT INTO {table} ({columns}) VALUES %s',
        }[out_style]

        return compile_mode, values

