  """Check all digests in manifest that are needed are present and used."""

  # Initialize dictionary to track digest presence and usage status
  digest_status = {
    digest: (False, False)
    for digest, _ in manifest_files
  }

  # Update the dictionary based on the provided digests
  for digest in digests_used:
    if digest in digest_status:
      digest_status[digest] = (True, True)

  # Check each digest in the manifest
  for _, (present, used) in digest_status.items():
    if not present:
      # Check if the manifest file exists
      manifest_file_path = self._path(manifest_files[hash(digest)])
      if not os.path.exists(manifest_file_path):
        raise FileNotFoundError(f"Manifest file {manifest_file_path} not found")
      # Read the manifest file content
      manifest_content = self._read_file(manifest_file_path)
      # Check if the digest is in the manifest
      if digest not in manifest_content:
        raise ValueError(f"Manifest file {manifest_file_path} does not contain digest {digest}")
      # Mark the digest as used
      digest_status[digest] = (True, True)
    elif not used:
      # Check if the digest is in the analyzed_vms
