def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # check if the inventory is empty or version is None
    if not inventory or version is None:
        return {}

    # initialize the result dictionary
    result = {}

    # iterate over each item in the inventory
    for item in inventory:
        # check if the version in the item is less than or equal to the given version
        if item['version'] <= version:
            # get the logical path from the item
            logical_path = item['logical_path']
            # get the content files from the item
            content_files = item['content_files']
            # add the logical path and its content files to the result dictionary
            if logical_path in result:
                result[logical_path].update(content_files)
            else:
                result[logical_path] = content_files

    return result

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for version_info in inventory:
        version_number = version_info['version']
        for item in version_info['items']:
            logical_path = item['logical_path']
            content_file = item['content_file']
            if version_number == version:
                if logical_path in logical_path_map:
                    logical_path_map[logical_path].add(content_file)
                else:
                    logical_path_map[logical_path] = {content_file}
    return logical_path_map

