import os
from os.path import abspath, isfile, exists

def files_list(path):
    if not path:
        raise ValueError("Path cannot be empty")
    paths = []
    for root, dirs, files in os.walk(path):
        if not files:
            continue
        for f in sorted(files):
            full_path = os.path.join(root, f)
            if isfile(full_path):
