import zipfile

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    z = zipfile.ZipFile(zip_path, 'r')
    for zinfo in z.infolist():
        file_name = zinfo.filename
        if zinfo.filename.endswith('/'):
            result[file_name] = {}
        else:
            pardir = zinfo.filename.rsplit('/', 1)[0]
            filename = zinfo.filename.rsplit('/', 1)[1]
            if pardir not in result:
                result[pardir] = {}
            result[pardir][filename] = z.read(zinfo)
    return result

