def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def absorb_impl(expr1, expr2):
        if isinstance(expr1, str) and isinstance(expr2, str):
            if expr1 in expr2:
                return str(expr2.replace(expr1, '', 1))
            elif expr2 in expr1:
                return str(expr1.replace(expr2, '', 1))
            else:
                return expr1
        elif isinstance(expr1, int) and isinstance(expr2, int):
            if expr1 == expr2:
                return expr1
            elif expr1 <= expr2:
                return expr1
            else:
                return expr2
        elif isinstance(expr1, float) and isinstance(expr2, float):
            if expr1 == expr2:
                return expr1
            elif expr1 <= expr2:
                return expr1
            else:
                return expr2
        else:
            raise ValueError("Unsupported type for expressions")

    def negate_absorb(expr1, expr2):
        if isinstance(expr1, str) and isinstance(expr2, str):
            if expr1 in expr2:
                return expr2.replace(expr1, '', 1)
            elif expr2 in expr1:
                return expr1.replace(expr2, '', 1)
            else:
                return expr1
        elif isinstance(expr1, int) and isinstance(expr2, int):
            if expr1 == expr2:
                return expr1
            elif expr1 <= expr2:
                return expr2
            else:
                return expr1
        elif isinstance(expr1, float) and isinstance(expr2, float):
            if expr1 == expr2:
                return expr1
            elif expr1 <= expr2:
                return expr2
            else:
                return expr1
        else:
            raise ValueError("Unsupported type for expressions")

    result = []
    for arg in args:
        if '&' in arg:
            a, b = arg.split('&')
            result.append(a if expect(absorb_impl, arg, '|')(a, b) else b)
        elif '|' in arg:
            a, b = arg.split('|')
            result.append(a if expect(absorb_impl, arg, '&')(a, b) else b)
        elif '!' in arg:
            if '*' in arg:
                a, b = arg.split('*')
                result.append(absorb_impl(a, negate_absorb(b, a)) if expect(absorb_impl, arg, '|')(a, b) else b)
            elif '*' not in arg:
                a, b = arg.split('/')
                result.append(absorb_impl(a, negate_absorb(b, a)) if expect(absorb_impl, arg, '&')(a, b) else b)
        else:
            result.append(arg)
    return result

