    absorption_rules = [('A & (A | B)', 'A'), ('A | (A & B)', 'A'), ('A & (~A | B)', 'A & B'), ('A | (~A & B)', 'A | B')]
    abs_exprs = []
    neg_abs_exprs = []
    for expr in args:
