import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    Args:
      commands: A list or tuple of commands to execute.
      args: A list of arguments for each command.
      cwd: The working directory for the commands (optional).
      verbose: Whether to print output to stdout (optional).
      hide_stderr: Whether to hide standard error (optional).
      env: A dictionary whose keys are environment variable names and whose values are environment variable values (optional).
    """
    for cmd in commands:
        try:
            if cwd:
                subprocess.check_call(cmd, shell=True, cwd=cwd, env=env)
            else:
                subprocess.check_call(cmd, shell=True)
        except subprocess.CalledProcessError as e:
            stderr = e.stderr.decode().strip() if hide_stderr else e.stderr.decode().strip() + '\n'
            if verbose:
                print("Error: ", stderr)

