def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    '''
    Call the given command(s).

    :param commands: `list`, a list of command pipelines to run in a subprocess.
    :param args: `dict`, a dictionary of arguments for each command.
    :param cwd: `str`, the current working directory.
    :param verbose: `bool`, whether to output each command's output.
    :param hide_stderr: `bool`, whether to hide command's stderr output.
    :param env: `dict`, environment variables to pass to the command.
    '''
    if not commands:
        return ''

    for idx, cmd in enumerate(commands):
        cmd_str = ' '.join(cmd)
        if args:
            prefix = '{}('
            suffix = ')'
        else:
            prefix = ''
            suffix = ''

        full_cmd_str = ' '.join([prefix, cmd_str, suffix])
        print(full_cmd_str) if verbose else None

        try:
            if hide_stderr:
                stdout = subprocess.check_output(cmd, cwd=cwd, env=env, stderr=subprocess.STDOUT, shell=False)
            else:
                stdout = subprocess.check_output(cmd, cwd=cwd, env=env, shell=False)

            if idx < len(commands) - 1:
                print(stdout.decode('utf-8'))
        except subprocess.CalledProcessError as e:
            if not hide_stderr:
                print(e.stderr.decode('utf-8'))
            raise ProgramError(f"Command '{full_cmd_str}' failed with exit code {e.returncode}")

