def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    if self._storage_is_root:
        return 0, 0

    objects = self._get_root_level_objects()

    num_objects = len(objects)
    good_objects = 0

    for obj in objects:
        if validate_objects:
            object_id, object_class = obj.get_id(), obj.get_class()

            if not self._catalog_is_valid(object_id):
                if show_warnings:
                    self._show_warning('Invalid root object ID: {0}'.format(object_id))
                return num_objects, good_objects
            else:
                good_objects += 1

        if check_digests:
            object_digest = self._get_root_object_digest(object_id)

            if not self._digest_is_valid(object_digest):
                if show_warnings:
                    self._show_warning('Invalid root object digest: {0}'.format(object_digest))
                return num_objects, good_objects

        num_objects += 1

    return num_objects, good_objects

