def next_version(version: str) -> str:
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "0.0.1"

    parts = version.split('.')
    parts[-1] = str(int(parts[-1]) + 1)

    return '.'.join(parts)

def next_version(version: str) -> str:
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.startswith("v"):
        version = version[1:]

    parts = version.split(".")
    if len(parts) == 1:
        if parts[0] == "0":
            return "v0.0.1"
        else:
            return "v{}.0.1".format(int(parts[0]) + 1)
    elif len(parts) == 2:
        if parts[0] == "0" and parts[1] == "0":
            return "v1.0.1"
        elif parts[1] == "0":
            return "v{}.1.1".format(int(parts[0]) + 1)
        else:
            return "v{}.{}1".format(int(parts[0]), int(parts[1]) + 1)
    elif len(parts) == 3:
        if parts[0] == "0" and parts[1] == "0" and parts[2] == "0":
