from packaging.specifiers import InvalidSpecifier

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Check if version_dirs is a list of strings
    if not all(isinstance(dir, str) for dir in version_dirs):
        raise TypeError("version_dirs must be a list of strings")

    # Check if version_dirs is in version sequence
    if not all(version_dirs[i] == str(i + 1) for i in range(len(version_dirs))):
        raise ValueError("version_dirs must be in version sequence (1, 2, 3...)")

    # Create an empty dictionary to store inventories
    inventories = {}

    # Iterate through version_dirs
    for dir in version_dirs:
        try:
            inventory = packaging.specifiers.Specifier.Parse(dir)
            inventories[dir] = inventory
        except InvalidSpecifier as error:
            tmpl = (
                "Inventory for {dir} must be a valid version specifier; {error}"
            )
            raise DistutilsSetupError(tmpl.format(dir=dir, error=error))

    # Keep a record of any content digests different from those in the root inventory
    root_inventory = inventories['1']
    content_digests = {
        content_digest: digest
        for content_digest, digest in self.content_digests.items()
        if digest != inventories['1'].parse(content_digest).parse(content_digest)
    }

    # Check if any content digests are different
    if content_digests:
        raise ValueError("Content digests different from those in the root inventory")

