    inventory_files = [os.path.join(version_inventory_dir, file) for file in os.listdir(version_inventory_dir)
                      if file.endswith('.json')]
    if not inventory_files:
        raise ValueError(f"No inventory files found in {version_inventory_dir}.")

    # Verify that all inventory files are valid JSON
    for inventory_file in inventory_files:
        try:
            with open(inventory_file, 'r') as f:
                inventory_data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in {inventory_file}: {e}")

    # Initialize a dictionary to hold content digest differences
    content_digest_diffs = {}

    # Compare content digests of each version inventory file
    for i in range(len(inventory_files) - 1):
        inventory_dir1 = inventory_files[i]
        inventory_dir2 = inventory_files[i + 1]
        inventory_file1 = os.path.join(inventory_dir1, 'inventory.json')
        inventory_file2 = os.path.join(inventory_dir2, 'inventory.json')

        try:
            with open(inventory_file1, 'r') as f1:
