        for key in inventory_data1['content_digests']:
            if key in inventory_data2['content_digests'] and inventory_data1['content_digests'][key] != inventory_data2['content_digests'][key]:
                content_digest_diffs[key] = inventory_data1['content_digests'][key]

    # Raise an error if there are any content digest differences
    if content_digest_diffs:
