def amend_bzparams(self, params, bug_ids):
    """
        Amend the Bugzilla params

        params: A dictionary of Bugzilla parameters to update
        bug_ids: A list of Bug IDs to update

        >>> bq = Bugsy()
        >>> bug_id_to_bzparams = {1234: {'field1': 'value1', 'field2': 'value2'},
                                    5678: {'field1': 'new_value1', 'field2': 'new_value2'}}
        >>> bq.amend_bzparams(bug_id_to_bzparams, [1234, 5678])
    """
    for bug_id, bzparams in bug_id_to_bzparams.items():
        if bug_id not in self._bug_cache:
            raise BugException("Bug ID not found in the cache")

        if len(bzparams) != len(self._bug_cache[bug_id]):
            raise BugsyException("Bug %d has incorrect number of fields" % bug_id)

        bug = self._bug_cache[bug_id]
        for field, value in bzparams.items():
            try:
                bug._bug[field] = value
            except KeyError:
                pass

        bug.bugzilla_put()

