import math

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if size[-1] == 'K':
        num = float(size[:-1])
        return int(num * 1024)
    elif size[-1] == 'M':
        num = float(size[:-1])
        return int(num * 1024 * 1024)
    elif size[-1] == 'G':
        num = float(size[:-1])
        return int(num * 1024 * 1024 * 1024)
    elif size[-1] == 'T':
        num = float(size[:-1])
        return int(num * 1024 * 1024 * 1024 * 1024)
    elif size[-1] == 'P':
        num = float(size[:-1])
        return int(num * 1024 * 1024 * 1024 * 1024 * 1024)
    elif size[-1] == 'E':
        num = float(size[:-1])
        return int(num * 1024 * 1024 * 1024 * 1024 * 1024 * 1024)
    elif size[-1] == 'Z':
        num = float(size[:-1])
        return int(num * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024)
    elif size[-1] == 'Y':
        num = float(size[:-1])
        return int(num * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024)
    else:
        return int(size)

