def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    def unescape(value):
        # Use urllib.parse.quote_plus to unescape URL arguments by replacing spaces and values with their encoded equivalents
        return urllib.parse.quote_plus(value)

    url_parts = url.split('&')
    new_url_parts = []

    for part in url_parts:
        if not part:
            continue
        if '=' in part:
            key, value = part.split('=', 1)
            if key.startswith('*'):
                key = key[1:]
                value = unescape(value)
                new_url_parts.append(f"{key}={value}")
            else:
                new_url_parts.append(part)
        else:
            new_url_parts.append(part)

    return '&'.join(new_url_parts)

def _replace_url_args(self, url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''

    url_parts = urllib.parse.urlparse(url)
    query_params = urllib.parse.parse_qs(url_parts.query)

    for key, value in url_args.items():
        query_params[key] = [value]

    new_query = urllib.parse.urlencode(query_params, doseq=True)
    new_parts = url_parts._replace(query=new_query)

    return urllib.parse.urlunparse(new_parts)

