def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    dividend, divisor = number, len(alphabet)
    digits, index, carry = [], 0, 0

    while dividend:
        if carry:
            for i in range(divisor):
                carry -= alphabet[index % dividend] == "0"
                index += 1
            carry = "1" if carry > 0 else "0"

        digit = alphabet[index % dividend]
        digits.insert(0, str(digit))
        dividend = dividend // divisor
        index = (index + 1) % divisor

    if padding is not None:
        missing_count = padding - len(digits)
        digits = [str(0)] * missing_count + digits

    return "".join(digits)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    result = []
    while number > 0:
        result.insert(0, alphabet[number % base])
        number //= base
    if padding is not None and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))
    return ''.join(result)

