import requests
from pathlib import Path
import os
import tarfile

def get_repo_archive(url: str, destination_path: Path) -> Path:
    if not isinstance(url, str) or not isinstance(destination_path, Path):
        raise TypeError("Both url and destination_path must be of type str and Path respectively")

    if not (url.endswith('.tar.gz') and destination_path.is_dir()):
        raise ValueError("the url must be a .tar.gz file and destination_path must be a directory")

    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"Failed to retrieve archive: {e}")

    with destination_path.absolute() as dst_dir, open(dst_dir / f'repo_extracted_{os.path.basename(url)}', 'wb') as file:
        for chunk in response.iter_content(chunk_size=8192):
            file.write(chunk)

    with tarfile.open(dst_dir / f'repo_extracted_{os.path.basename(url)}', 'r:gz') as tar:
        tar.extractall(dst_dir)

    return dst_dir

