import subprocess
from pathlib import PosixPath, Path
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError("Archive file not found: {}".format(archive_path))

    try:
        subprocess.run(
            [
                Tar, "--extract", "-C", tmp_path, "-", archive_path
            ],
            check=True,
        )

        # Assuming the extracted files contain a repo URL in one of the files,
        # getting the repository URL from the first file found.
        repo_url = None
        for file_name in os.listdir(tmp_path):
            if file_name.endswith(".tar.gz") or file_name.endswith(".tar.bz2"):
                repo_url = find_repo_url(Path(file_name), tmp_path)
                break

        if not repo_url:
            raise ValueError("No repository URL found in the extracted files.")

        return repo_url

    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(
            f"Unarchive process failed with exit code {e.returncode}: {e.output}"
        )

    except FileNotFoundError as e:
        raise FileNotFoundError(f"File {archive_path} not found: {e}")

