import subprocess

def addignored(ignored):
    """ Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""

    def git(args, error_message, cwd=context.parent_dir, **error_kwargs):
        output, status = command_output("git {0}".format(args), cwd=cwd)
        if status != 0:
            error_kwargs['output'] = output
            error_kwargs['directory'] = context.parent_dir
            raise HarpoonError(error_message, **error_kwargs)
        return output

    start = git("ls-files --status --exclude-standard", "Failed to find files that have been added or modified")
