import datetime

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")

    number = int(parts[0])
    unit = parts[1].lower()

    if unit in ["years", "year"]:
        return datetime.timedelta(years=number)
    elif unit in ["months", "month"]:
        return datetime.timedelta(months=number)
    elif unit in ["weeks", "week"]:
        return datetime.timedelta(weeks=number)
    else:
        raise ValueError("Unsupported unit")

import datetime

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency == "always":
        return None
    if isinstance(frequency, str):
        match = re.match(r"(\d+)\s*([dwmy])", frequency)
        if match:
            value = int(match.group(1))
            unit = match.group(2)
            if unit == "w":
                return datetime.timedelta(weeks=value)
            elif unit == "d":
                return datetime.timedelta(days=value)
            elif unit == "m":
                return datetime.timedelta(months=value)
            elif unit == "y":
                return datetime.timedelta(years=value)
            else:
                raise ValueError(f"Invalid frequency unit '{unit}'")
        else:
            raise ValueError(f"Invalid frequency format: {frequency}")
    else:
        raise TypeError(f"Expected 'str' or 'None', got {type(frequency)}")

if frequency is None or frequency.lower() == 'always':
        return None
    r = re.match(r'\s*(\d+)\s*([dhm])\s*$', frequency)
    if r:
        number, unit = int(r.group(1)), r.group(2)
        if unit.lower() == 'd':
            return datetime.timedelta(days=number)
        elif unit.lower() == 'h':
            return datetime.timedelta(hours=number)
        elif unit.lower() == 'm':
            return datetime.timedelta(minutes=number)
        else:
            raise ValueError('Invalid frequency.')
    else:
        raise ValueError('Invalid frequency.')

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    units = {
        "ms": 1,
        "s": 1000,
        "m": 60000,
        "h": 3600000,
        "d": 86400000,
        "w": 604800000
    }
    match = re.match(r^(\d+)\s*(\w+([^s]?))$, frequency)
    if not match:
        raise ValueError("Invalid frequency format")
    value, unit = int(match.group(1)), match.group(2)
    if unit not in units:
        raise ValueError("Unsupported unit: `%s`" % unit)
    return datetime.timedelta(value*units[unit])

