import re
def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    def path_to_glob(path):
        if '%' in path or '*' in path or '?' in path or '[' in path or ']' in path:
            return path
        else:
            if path.endswith('.txt'):
                return f'**/{path}**'
            else:
                return f'sh:{path}/**'

    return [path_to_glob(p) for p in find_paths]

import re

def make_find_paths(find_paths):
    result = []
    for path in find_paths:
        if isinstance(path, str):
            if path.startswith("pp:"):
                result.append(path)
            else:
                # Attempt to expand wildcards
                result.extend(list(glob.glob(path, recursive=True)))
        elif isinstance(path, os.PathLike):
            result.extend(list(glob.glob(path.as_posix(), recursive=True)))
        elif isinstance(path, (list, tuple)):
            combined_pattern = ".*.*"
            for item in path:
                if isinstance(item, str):
                    combined_pattern += "{}/".format(re.escape(item))
                elif isinstance(item, os.PathLike):
                    combined_pattern += "{}/".format(item.as_posix())
                else:
                    raise TypeError("Item in find_paths should be string or path-like, not {0:s}".format(type(item)))
            # Determine recursion level
            recursion = 100  # Default to 100 if not provided
            if combined_pattern.endswith("**") and "**" in combined_pattern:
                level = int(combined_pattern.split("/*")[1].split("**")[0])
                if level.isdigit():
                    recursion = int(level)
                else:
                    raise ValueError("Invalid recursion level in glob pattern")
            result.extend(list(glob.glob(combined_pattern, recursive=recursion)))
    return result

