                raise FileNotFoundError("Configuration file not found: %s" % filename)

            if overrides is not None:
                # Apply overrides to the configuration
                parsed_config = _apply_overrides(filename, overrides)
            else:
                parsed_config = _parse_config_from_file(filename)

            parsed_configs[filename] = parsed_config
        except Exception as e:
            log.error("Error loading or parsing configuration file %s: %s" % (filename, e))
