    def __init__(self, ticks: int, tz: Union[None, datetime.tzinfo] = None):
        if not 0 <= ticks < 86400000000000:
            raise ValueError("Time ticks must be between 0 and 86400000000000")
        self.ticks = ticks
        self.tz = tz

    def __str__(self) -> str:
        return f"{self.ticks}ns since midnight in {self.tz}"

    @classmethod
    def from_ticks(cls, ticks: int, tz: Union[None, datetime.tzinfo] = None) -> "Time":
        """
        Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        return cls(ticks, tz=tz)

