from typing import *  # NOQA

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    new_text = text
    code_start = None
    prev_char = None

    for char_index, char in enumerate(text):
        if char_index == 0:
            prev_char = char
            if char in (" ", "\t", "#", "!", "*", "/", "=", "<", ">", ".", ",", ";", " ", "\t"):
                continue

        if char in (" ", "\t", "#", "!", "*", "/", "=", "<", ">", ".", ",", ";", " ", "\t"):
            if code_start is not None:
                code_start += 1
            prev_char = char
            continue

        if (code_start and prev_char != "=") or (char == "=" and code_start > 1):
            if code_start >= 0:
                tag = text[code_start:]
                if code_start == 0 and "\n" in tag or "\r\n" in tag:
                    tag = tag.lstrip()
                tags.add(tag)
            code_start = -1
            prev_char = char
            continue

        if char == "@":
            if code_start >= 0:
                text = text[:code_start] + new_text[code_start:]
            code_start = char_index + 1

        if char == "$":
            code_start = char_index + 1
            prev_char = char

    if code_start >= 0:
        new_text = text[:code_start] + new_text[code_start:]

    if replacer:
        new_text = replacer(new_text)

    return tags, new_text

