      result.append('<a href="{0}">{0}</a>'.format(word))
    elif word.startswith("#") and ": " in word:
      section, text = word.split(": ")
      result.append('<a name="{0}" onclick="scrollIntoView({1})">{1}</a>'.format(section, text))
