    """Test a word whether it could be accepted as a tag."""
    tag = tag.replace('"', '')  # removing any double quotes that might appear around the tag
    if len(tag) == 0:
        return False
    if not tag[0].isalpha():
        return False
    if not tag[1:].isalnum():
        return False
    return True

