def verify_relayable_signature(self, public_key, doc, signature):
    """ Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not public_key:
        raise ValueError("Public key must be provided")
    if not doc:
        raise ValueError("Document must be provided")
    if not signature:
        raise ValueError("Signature must be provided")

    # Create a verification key using the public key
    verification_key = SigningKey.from_string(public_key, curve='secp160r1')

    # Verify the XML document using the signature
    if verification_key.verify_signature(doc, bytes.fromhex(signature)):
        return True
    else:
        return False

