def extend_cli(self, root_subparsers):
        """
        Adds the spec cli options to the main entry point.

        :param subparser: the subparser object to extend.
        """
        if not root_subparsers:
            raise ValueError("root_subparsers must be provided")

        for name, spec in self.displays.items():
            if spec.default:
                subparser.add_argument("--" + name, required=spec.default.parsed_by_pos, default=spec.default.parsed_from_user)
            else:
                subparser.add_argument("--" + name, metavar=", ".join(map(str, spec.all_choices)), help=spec.description)

            if spec.default:
                spec.default.setup_user_interface(root_subparsers)

