def strip_root(path, root):
    """Remove root from path, throw exception on failure."""

    try:
        if path.startswith(root):
            stripped_path = path[len(root):]
            if stripped_path == '':  # Unnecessary check due to string joining?
                raise ValueError("Empty path after stripping {0}".format(root))
            return stripped_path
        else:
            raise ValueError("Path {0} does not start with {1}".format(path, root))
    except ValueError as err:
        raise Foundation.exceptions.PathValidationError(
            "!> {0} | Cannot strip '{1}' root from '{2}' path: '{3}'".format(__name__, root, path, err))
    except Exception as error:
        raise foundations.exceptions.PathStripError(
            "!> {0} | Cannot strip '{1}' root from '{2}' path: '{3}'".format(__name__, root, path, error))

